const ctx = $input.first().json.ctx;
const DASH = 'https://ast.tecknuovo.com/#';
const email = 'kiera.battersby@tecknuovo.com';
const items = [];
for (const r of (ctx.risks || [])) items.push({ icon: ':red_circle:', kind: 'risk', ...r });
for (const o of (ctx.opps || [])) { if (items.length >= 3) break; items.push({ icon: ':bulb:', kind: 'opportunity', ...o }); }
if (!items.length) {
  return [{ json: { email, text: ':sunrise: *Morning Kiera - nothing needs you today.* All accounts steady; new signals will land here as calls come in.', mappingSql: null } }];
}
const lines = [':sunrise: *Morning Kiera - your ' + (items.length === 1 ? 'priority' : items.length + ' priorities') + ' for today*'];
items.forEach((it, i) => {
  lines.push(it.icon + ' *' + (i + 1) + '. ' + it.summary + '*' + (it.account ? '  _(' + it.account + ')_' : ''));
  if (it.suggested_action) lines.push('     ' + it.suggested_action);
  lines.push('     <' + DASH + '/delivery?signal=' + it.id + '|Open on the dashboard ->');
});
if (Number(ctx.new_count) > 0) lines.push(':memo: ' + ctx.new_count + ' new signal' + (Number(ctx.new_count) === 1 ? '' : 's') + ' since yesterday await a quick review.');
lines.push('_Reply "done 1", "not a risk 2" - or ask me anything about your accounts._');
const e = (s) => String(s).split("'").join("''");
const values = items.map((it, i) => "((SELECT COALESCE((SELECT slack_user_id FROM slack_users WHERE lower(email)='" + email + "'), '" + email + "')), " + (i + 1) + ", '" + e(it.id) + "')").join(',');
const mappingSql = 'DELETE FROM brief_items WHERE recipient IN (SELECT COALESCE((SELECT slack_user_id FROM slack_users WHERE lower(email)=\'' + email + '\'), \'' + email + '\')); INSERT INTO brief_items (recipient, item_no, signal_id) VALUES ' + values + ';';
return [{ json: { email, text: lines.join('\n'), mappingSql } }];
